HERO_STR_STATIC(hero_str_279c58a0, "this character literal never closes \342\200\224 write one character between single quotes: 'a'");
HERO_STR_STATIC(hero_str_657e57b2, "escape the backslash: `'\\\\'`");
HERO_STR_STATIC(hero_str_5521914, "'\\\\'");
HERO_STR_STATIC(hero_str_29539e50, "this string never closes \342\200\224 a hole opened with `{` and the line ended before its `}` and the closing `\"`");
