HERO_STR_STATIC(hero_str_6063861c, "`, so it has no size");
HERO_STR_STATIC(hero_str_163ad468, "` contains itself, so it has no size");
HERO_STR_STATIC(hero_str_17e9d1c, ", then ");
HERO_STR_STATIC(hero_str_3f0ee1d7, "every value is an independent copy, so `");
