HERO_STR_STATIC(hero_str_665b55e0, "the linker cannot find `");
HERO_STR_STATIC(hero_str_37d5e19d, "`, and no group in this program says which library has it");
HERO_STR_STATIC(hero_str_633fc766, "`, and a header is not a library: write `extern \"");
HERO_STR_STATIC(hero_str_1f2cc982, "\" link \"<library>\"` \342\200\224 `math.h` needs `link \"m\"` on Linux and the BSDs, where it is a separate library");
